        let bgsw1: [String: String] = ["brett.erkl.titel": "Was isch d Lag vom Brätt?", "brett.erkl.was": "Isch dis Handy während de Session fescht ufem Brätt, misst sin Chreisel, wie s Brätt nickt und rollt – diräkt a de Quelle statt am Handglänk.", "brett.erkl.wie": "So gaht's: Handy wasserdicht ipackt flach ufem Deck befestige und d Ufnahm i de Pumpfoil-App ufem Handy starte. D Uhr cha gliichzitig mitlaufe. Dass s Handy am Brätt gsi isch, merkt d Uswärtig meischtens sälber.", "brett.erkl.bringt": "Was es bringt: Du gsehsch, wie ruhig dis Brätt bim Pumpe liit, wie fescht es pro Pump nickt und rollt und öb sich das zwüsche Foils, Kurve und Grade unterscheidet. Jedi söttigi Ufnahm hilft usserdem, d Pump-Erkännig für d Uhr z verbessere.", "brett.erkl.daten": "Was für Date du überchunsch: Nicke und Rolle pro Pump, Schräglag, Takt, Kurve gäge Grad und de Hub (d Uf- und Abbewegig, sobald de Pumptakt sicher erkännt isch) – pro Lauf und do als Übersicht über alli Läuf und pro Foil.", "brett.erkl.mehr": "Meh dezue", "region.earth": "Ärde", "region.eu": "Europa", "region.af": "Afrika", "region.as": "Asie", "region.na": "Nordamerika", "region.sa": "Südamerika", "region.oc": "Ozeanie", "profile.landNone": "Kei Aagab", "share.errImage": "Bild het nöd chöne erstellt werde", "spot.windTitle": "Windfänschter", "spot.windText": "{n} Wind-Sessions, meischtens bi {a}–{b} km/h", "spot.windNote": "Vo wo dä Wind bi de Wing-, Kite- und Parawing-Sessions a däm Spot cho isch (Modällwind).", "tab.noData": "Do häts no kei Date.", "fontscale.label": "Schriftgrössi", "fontscale.hint": "Für besseri Läsbarkeit alles grösser darstelle.", "sd.avgHrTotal": "Ø Puls total", "sd.whoLiked": "Wer?", "sd.likes": "Likes", "comments.title": "Kommentär", "comments.empty": "No kei Kommentär. Schriib de erscht!", "comments.placeholder": "Kommentar schriibe …", "comments.offOwner": "Kommentär sind für dini Sessions abgschaltet.", "comments.offLink": "Im Profil iischalte", "comments.settingHint": "Anderi chönd under dine Sessions kommentiere. Du chasch frömdi Kommentär under dine Sessions lösche. Abgschaltet sind Kommentär für alli usbländet, au die, wo scho gschribe sind.", "comments.settingSwitch": "Kommentär under mine Sessions erlaube", "act.title": "Nöii Kommentär & Likes", "act.comment": "het kommentiert", "act.like": "gfallt dini Session", "act.likeMany": "und {n} wiiteri finded dini Session guet", "act.session": "Session vom {d}", "profile.land": "Nationalität", "profile.landHint": "Freiwillig. Wer sie aagit, überchunnt sini Flagge i de Bestelischte, ihre Bilder zum Teile und uf de Profilsiite.", "tab.events": "Events", "tab.logbook": "Logbuech", "tab.rules": "Regle", "team.einladungUngueltig": "De Iiladigslink gilt nüm. Frog d Teamleitig nach eme neue.", "team.feed30": "Sessions vo de Team-Mitglieder us de letschte 30 Täg.", "team.alleMeine": "Alli mini Teams", "sessions.uploadReplaceAsk": "Die Fahrt isch scho da (Session #{id}), aber d Datei isch e anderi. Alti Session lösche und dur die Datei ersetze?\n\nNur zueschnide gaht au ohni neui Datei: i de Session unter „{trim}“."]
