        let bgsw2: [String: String] = ["team.regeln.intro": "So funktioniered Teams uf pumpfoil.org: wer was gseht, wie gwertet wird und was bim Lösche passiert.", "team.regeln.was.titel": "Was isch es Team?", "team.regeln.was.text": "E feschti Gruppe mit eigene Bestelischte, Events und emne Team-Chat.\nJede cha Teams gründe, au mehreri, und i mehrere Teams sii.\nEs neus Team lauft sofort, über Iiladigslinks.", "team.regeln.rollen.titel": "Rolle", "team.regeln.rollen.text": "D Teamleitig dörf alles: Iistellige, Bestelischte, Events, Moderatore bestimme, d Leitig übergä und s Team lösche.\nModeratore nämed Aafroge aa oder lehned sie ab, nämed Mitglieder use und leged Events aa. Susch ändered sie nüt.\nMitglieder gsehnd alles im Team und chönd jederziit uustrete.\nD Leitig cha erscht uustrete, wenn sie d Leitig übergä het.", "team.regeln.beitreten.titel": "Biitrete", "team.regeln.beitreten.text": "Lat es Team Aamäldige zue, staht uf sinere Siite en Chnopf „Biitrete“. Je nach Iistellig isch mer sofort Mitglied, oder d Leitig bzw. en Moderator entscheidet.\nEs git zwei Iiladigslinks: eine, mit dem mer sofort Mitglied isch, und eine, mit dem mer e Aafrog stellt. Beidi gits au als QR-Code.\nWer no kei Konto het, macht eis und isch drnoch grad im Team bzw. het aagfrogt.\nEn neue Link ersetzt de alt, de alt gilt denn nüm.\nMit jedem Biitritt bisch iiverstande, dass d Bestelischte vom Team öffentlich chönd sii, au wenn sie's grad nöd sind.\nBi ere Aafrog gsehnd d Leitig und d Moderatore, a wele Spots und i wele Sportarte du bis jetzt unterwägs gsi bisch (nur d Zahl vo de Sessions).", "team.regeln.oeffentlich.titel": "Was öffentlich isch", "team.regeln.oeffentlich.text": "Intern dörf es Team alles. Gäge usse taucht's erscht uf, wenn mir Name, Adrässe, Beschriibig, Wappe und Farb eimal aagluegt und freigä händ.\nS Teambild gaht dur di glich Freigab wie s Wappe. Weli Usschnitt mer gseht, wählt d Leitig ohni neui Freigab; nimmt si s Bild use, isch es sofort au usse wäg.\nÄnderet es freigäs Team sin Uftritt, gilt das im Team sofort, gäge usse erscht nach erneuter Freigab.\nFreigäni Teams stönd uf de Siite „Alli Teams“, ihri laufende und chömende Events i de Community.\nSchaltet d Leitig d Bestelischte öffentlich, gseht sie jede, au ohni Aamäldig, aber nume Platz, Aazeigname, Initiale und Wert. Sessions, Spots, Datum und Profilbilder gsehnd nume Aagmeldeti.\nSuechmaschine nämed Teamsiite nöd uf.\nWer d Mitgliederlischte gseht, bestimmt d Leitig: nume Mitglieder oder alli Aagmeldete.", "team.regeln.bestenlisten.titel": "Bestelischte", "team.regeln.bestenlisten.text": "Pro Person zählt nume ein Iitrag: de bescht Wert us einere Session, oder bi Summe alles im gwählte Ziitruum zäme.\nEs zähled alli Sessions vo de Mitglieder, au die vo vor em Biitritt. Wer uustritt, verschwindet sofort us de Lischte.\nBi Events gilt das nur bis zum Änd, lueg under „Events“.\nEs gälted die gliiche Filter wie bi de Community-Rekord: glöschti, gmeldeti, nöd zuegordneti und laufendi Ufnahme zähled nöd.\nJedi Bestelischte cha uf e Sportart, es Foil-Band, Ufnahme mit Bewegigsdate, s Handy am Brätt oder d Teamspots iigschränkt werde.\nIsch „Ort verberge“ aa, zählt d Session nie für en bestimmte Spot.\nBi Gliichstand isch vorne, wer de Wert zerscht gfahre isch.", "team.regeln.statistik.titel": "Teamsumme", "team.regeln.statistik.text": "Über de Bestelischte stönd d Summe vo allne Mitglieder im gwählte Ziitruum: Pumps, On-Foil-Strecki und -Ziit, Sessions, Läuf und wie vill Mitglieder aktiv gsi sind.\nE Ranglischte Team gäge Team gits extra nöd.", "team.regeln.logbuch.titel": "Logbuech", "team.regeln.logbuch.text": "S Logbuech hebt fescht, wer wänn welle Teamrekord broche het. Es wird jedi Nacht nachgfüehrt.\nDe erscht Iitrag vo einere Bestelischte isch de Stand i de erschte Nacht nach em Aalege.\nBi Beschtwärt zählt jedi Steigerig, au di eige. Bi Summe zählt's nume, wenn öpper d Spitze übernimmt.\nSinkt en Rekord, will e Session glöscht worde isch oder öpper uustrete isch, wird das still nachzoge, ohni Iitrag.", "team.regeln.chat.titel": "Team-Chat", "team.regeln.chat.text": "De Team-Chat läsed und schriibed nume aktivi Mitglieder. Wer nume aagfrogt het, gseht ne nöd.\nEr taucht für anderi niene uf, au nöd under de aktive Chats.\nWer uustritt oder usegno wird, verlüürt de Zuegang sofort und überchunnt kei Benachrichtigunge meh.", "team.regeln.loeschen.titel": "Team lösche", "team.regeln.loeschen.text": "Lösche cha nume d Teamleitig, und nume wenn sie de Teamname zum Bestätige iitippt.\nDenn isch s Team für alli wäg: Mitgliedschafte, Bestelischte, Logbuech, Events und de Team-Chat. D Date bhalted mir vorläufig, demit mer es us Versehe glöschts Team wieder härestelle chönd.\nD Adrässe vom Team blibt gsperrt und wird nie amne andere Team vergä.", "team.regeln.konto.titel": "Wenn es Konto glöscht wird", "team.regeln.konto.text": "D Person verschwindet us allne Teams, Bestelischte und au us iigfrorene Event-Resultat. D Plätz drunder rucked uf.\nHet sie es Team gleitet, übernimmt de dienschtältischt Moderator, susch s dienschtältischt Mitglied. Isch niemer meh da, wird s Team glöscht.", "team.regeln.haftung.titel": "Haftig", "team.regeln.haftung.text": "Events veranstalted d Teams sälber. pumpfoil.org het kei Iifluss uf Events und uf Zuesage, wo drin gmacht wärded, ob finanziell oder andersch, und übernimmt dafür kei Verantwortig. De Rächtswäg isch usgschlosse. Zahlige und alli andere Abmachige regled Veranstalter und Teilnähmer unabhängig vo pumpfoil.org.\nGnau so übernimmt pumpfoil.org kei Verantwortig defür, dass gmässni Wärt und Date stimmed oder nöd manipuliert worde sind. Azeigt wird, was de öffentlich Quellcode uf GitHub us de ufeglade Date usrächnet; wiiteri Zuesage gits kei.", "team.regeln.events.titel": "Events", "notif.typeComment": "Kommentär zu mine Sessions", "home.topCommented": "Am meischte kommentiert", "theme.dark": "Dunkel", "theme.light": "Häll", "tech.hLong": "Läuf ab 20 s – ruhige Mittelteil", "tech.hShort": "Läuf under 20 s – ganze Lauf", "tech.lShort": "Läuf zwüsche 5 und 20 s, jewiils inkl. Start und Änd.", "tech.allRuns": "Alli Läuf", "account.tabGuide": "Aaleitig", "tab.watchSettings": "Iistellige", "account.tabConnect": "Verbinde", "account.tabFaces": "Ziiferblätter / Datefälder", "account.tabAlarm": "On-Foil Alarm", "account.tabCompat": "Kompatibilität", "account.toLayouts": "Eigeni Layouts", "tab.watchSettingsUhr": "Uhr-Iistellige", "guide.appleSub": "watchOS 9+", "guide.a.s1Title": "1. App installiere:", "guide.a.s1": "usem App Store.", "guide.a.s2Title": "2. Verbinde — optional:", "guide.a.s2a": "Du chasch sofort ohni Konto ufnäh („Spöter verbinde“) und d Session spöter ufelade. Zum Zuordne: i de Watch-App „Verbinde“ → „Pairing-Code mache“ — de aazeigti Code da im Tab"]
        mgsw.merge(bgsw2) { a, _ in a }
        let bgsw3: [String: String] = ["guide.a.s2b": "ygäh.", "guide.a.s3Title": "3. Datefälder:", "guide.a.s3": "direkt uf de Uhr wüschbari Syte (yystellbar im Tab „Datefälder“). Stopp-Chnopf am Aafang und Ändi vo de Syte.", "guide.a.s4Title": "4. Ufnäh:", "guide.a.s4": "App ufmache → Start → foile → Stop. Ufnahm lauft au offline; Sync passiert automatisch, sobald online.", "guide.wearSub": "Samsung Galaxy Watch, Google Pixel Watch …", "guide.w.s1Title": "1. App uf de Uhr installiere:", "guide.w.s1": "de Play Store uf de Uhr ufmache und nach „Pumpfoil“ sueche.", "guide.w.s1Note": "De Play Store uf em Händy installiert d Händy-App — d Uhre-App isch e eigeni Installation, direkt uf de Uhr.", "guide.w.s2Title": "2. Verbinde — optional:", "guide.w.s2a": "wie bi de Apple Watch — ohni Konto ufnäh isch möglich, spöter verbinde; oder i de Uhr-App „Verbinde“ → „Pairing-Code mache“ und de Code da im Tab", "guide.w.s2b": "ygäh.", "guide.w.s3Title": "3. Datefälder:", "guide.w.s3": "wüschbari Syte, yystellbar im Tab „Datefälder“.", "guide.w.s4Title": "4. Ufnäh:", "guide.w.s4": "App ufmache → Start → foile → Stop. Offline-Ufnahm + automatische Sync.", "guide.amazfitSub": "Unser Recorder läuft auf Amazfit-Uhren mit Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 u. a.).", "guide.z.store": "Hol die Zepp-App und finde Pumpfoil in deren integriertem App Store:", "guide.z.s1": "Installiere die Zepp-App (oben) und verbinde deine Amazfit dort wie gewohnt.", "guide.z.s2": "In der Zepp-App: Profil → deine Amazfit → App Store → „Pumpfoil“ suchen → Installieren.", "guide.z.s3": "Öffne Pumpfoil auf der Uhr, wische zu ›Verbinden‹ für einen Code und gib ihn ein unter ", "guide.z.s4": "Drücke START zum Aufzeichnen. GPS und Puls werden automatisch über WLAN/Telefon hochgeladen.", "guide.huaweiSub": "Üse Recorder lauft uf de HUAWEI WATCH 5 (HarmonyOS 5/6). Nach em Kopple ladet d Uhr sälber ufe – ohni Handy-App.", "guide.h.s1": "Mach uf de Uhr d AppGallery uf, such „Pumpfoil“ und installier d App