        let bdeAT1: [String: String] = ["brett.erkl.titel": "Was ist die Lage des Bretts?", "brett.erkl.was": "Liegt dein Handy während der Session fest auf dem Brett, misst sein Kreisel, wie das Brett nickt und rollt – direkt an der Quelle statt am Handgelenk.", "brett.erkl.wie": "So geht's: Handy wasserdicht verpackt flach auf dem Deck befestigen und die Aufnahme in der Pumpfoil-App auf dem Handy starten. Die Uhr kann gleichzeitig mitlaufen. Dass das Handy am Brett lag, erkennt die Auswertung meist von selbst.", "brett.erkl.bringt": "Was es bringt: Du siehst, wie ruhig dein Brett beim Pumpen liegt, wie stark es je Pump nickt und rollt und ob sich das zwischen Foils, Kurven und Geraden unterscheidet. Jede solche Aufnahme hilft außerdem, die Pump-Erkennung für die Uhr zu verbessern.", "brett.erkl.daten": "Welche Daten du bekommst: Nicken und Rollen je Pump, Schräglage, Takt, Kurve gegen Gerade und den Hub (die Auf- und Abbewegung, sobald der Pumptakt sicher erkannt ist) – je Lauf und hier als Übersicht über alle Läufe und je Foil.", "brett.erkl.mehr": "Mehr dazu", "region.earth": "Erde", "region.eu": "Europa", "region.af": "Afrika", "region.as": "Asien", "region.na": "Nordamerika", "region.sa": "Südamerika", "region.oc": "Ozeanien", "profile.landNone": "Keine Angabe", "share.errImage": "Bild konnte nicht erzeugt werden", "spot.windTitle": "Windfenster", "spot.windText": "{n} Wind-Sessions, meist bei {a}–{b} km/h", "spot.windNote": "Woher der Wind bei den Wing-, Kite- und Parawing-Sessions an diesem Spot kam (Modellwind).", "tab.noData": "Hier gibt es noch keine Daten.", "fontscale.label": "Schriftgröße", "fontscale.hint": "Für bessere Lesbarkeit alles größer darstellen.", "sd.avgHrTotal": "Ø Puls gesamt", "sd.whoLiked": "Wer?", "sd.likes": "Likes", "comments.title": "Kommentare", "comments.empty": "Noch keine Kommentare. Schreib den ersten!", "comments.placeholder": "Kommentar schreiben …", "comments.offOwner": "Kommentare sind für deine Sessions ausg'schaltet.", "comments.offLink": "Im Profil einschalten", "comments.settingHint": "Andere können unter deinen Sessions kommentieren. Du kannst fremde Kommentare unter deinen Sessions löschen. Ausg'schaltet sind Kommentare für alle ausgeblendet, a schon geschriebene.", "comments.settingSwitch": "Kommentare unter meinen Sessions erlauben", "act.title": "Neue Kommentare & Likes", "act.comment": "hat kommentiert", "act.like": "gefällt deine Session", "act.likeMany": "und {n} weitere mögen deine Session", "act.session": "Session vom {d}", "profile.land": "Nationalität", "profile.landHint": "Freiwillig. Wer sie angibt, bekommt seine Flagge in den Bestenlisten, ihren Bildern zum Teilen und auf der Profilseite.", "tab.events": "Events", "tab.logbook": "Logbuch", "tab.rules": "Regeln", "team.einladungUngueltig": "Der Einladungslink gilt nimma. Frag die Teamleitung um an neuen.", "team.feed30": "Sessions der Team-Mitglieder aus den letzten 30 Tagen.", "team.alleMeine": "Alle meine Teams", "sessions.uploadReplaceAsk": "Diese Fahrt ist schon da (Session #{id}), aber die Datei ist eine andere. Alte Session löschen und durch diese Datei ersetzen?\n\nNur zuschneiden geht auch ohne neue Datei: in der Session unter „{trim}“."]
