        let bdeAT4: [String: String] = ["guide.cap.aStart": "Start", "guide.cap.aAlarm": "Alarm wählen + Auslösen", "guide.cap.aStop": "Stop", "guide.cap.aUpload": "Upload nach dem Stopp", "guide.settings.title": "Einstellungen für deine Uhr", "guide.settings.intro": "Sobald die Uhr verbunden ist, findest du unter ", "guide.settings.intro2": " zu jeder Uhr zwei Regler. Sie wirken auf die Uhr selbst — sie übernimmt sie beim nächsten Start der App, ohne Update. Wenn dir die Akkulaufzeit wichtig ist, sind das die Stellschrauben.", "guide.settings.recordTitle": "Aufzeichnungsmodus (alle Uhren):", "guide.settings.record": "25 Hz, 10 Hz oder nur GPS. 10 Hz spart Akku und kostet fast nichts — wir haben beide Raten über dieselben Sessions gerechnet: der Pump-Zähler weicht um weniger als ein halbes Prozent ab, und welche Abschnitte als Foilen zählen, ist zu 99,9 % identisch.", "guide.settings.gnssTitle": "Satellitensysteme (nur Garmin):", "guide.settings.gnss": "Voreingestellt ist die beste Stufe, die deine Uhr kann — alle Systeme über zwei Frequenzbänder. Die findet die Position am schnellsten und hält sie am besten, kostet aber deutlich Akku. „Ohne zweites Frequenzband“ behält alle Systeme und lässt nur das teure Extraband weg: der größte Spareffekt bei kleinstem Verlust.", "guide.settings.gpsWarn": "Nur GPS spart am meisten, wirft aber Pump-Zähler, Kadenz und Gleitphasen komplett weg — also genau die Zahlen, für die diese App da ist. Wähle es nur, wenn deine Uhr sonst nicht durchhält.", "guide.settings.zepp": "Bei Amazfit wirkt der Aufzeichnungsmodus noch nicht — die Uhr nimmt mit ihrer eigenen Rate auf. Sprache, Pausenansicht und eigene Layouts holt sie sich dagegen von hier.", "watches.title": "Unterstützte Uhren", "watches.intro": "Wöche Uhr liefert wöche Daten — du entscheidest. Mir wolln langfristig olle gängigen Sportuhren aunbinden.", "watches.colDevice": "Uhr", "watches.colGps": "GPS · Distanz · Speed", "watches.colHr": "Puls", "watches.colPump": "Pumps & Gleitphasen", "watches.colStatus": "Status", "watches.foot": "Pumps & Gleitphasen brauchn Roh-Beschleunigung (≥25 Hz) direkt vo da Uhr. GPS-Stats lassn si bei vüle Marken aa per FIT-/Datenimport auswertn.", "watches.legYes": "voll unterstützt", "watches.legPartial": "eingeschränkt", "watches.legNo": "nicht verfügbar", "watches.linkAccount": "Konto Verknüpfung verfügbar", "watches.linkViaSuunto": "über Mi Fitness → Suunto", "watches.nGarmin": "Ältere Modelle ohne Roh-Accel: GPS-Stats werden trotzdem ausgewertet.", "watches.nApple": "Roh-Beschleunigung über Core Motion.", "watches.nWear": "Läuft auf jeder Wear-OS-3+-Uhr — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "Sensor-Zugriff je nach Modell.", "watches.nHuaweiW5": "Lädt nach dem Koppeln per Code selber hoch, ohne Handy-App. Neu in der AppGallery.", "watches.nHuawei": "In Arbeit: Aufnahme auf der Uhr, Übertragung über die Pumpfoil-App auf einem Android-Handy. Welche Daten die Uhren liefern, muss noch getestet werden.", "watches.nPolar": "Konto verknüpfen → Trainings importieren (GPS + HR). Den hochfrequenten Accel-Stream für die Pump-Erkennung liefert der API-Export net (nur via separatem BLE-Sensor).", "watches.nSuunto": "Konto verknüpfen → Trainings importieren (GPS + HR). Den hochfrequenten Accel-Stream für die Pump-Erkennung liefert der FIT-Export (no) net.", "watches.nXiaomi": "Kane App auf da Uhr möglich (Xiaomi lasst kane fremden Apps zua). Dafür schickt Mi Fitness deine Trainings offiziell in die Suunto-App — verknüpf Suunto und sie landen bei uns. Anleitung unter „Konten verknüpfen“.", "watches.nFitbit": "Drittanbieter-Apps wurden eingestellt.", "watches.nStrava": "Import wär technisch machbar, liefert per API aber kein hochfrequentes Roh-Accel (also keine Pump-Erkennung) und steht hinter Paywall + API-Auflagen, die nicht zum offenen Projekt passen — daher bewusst nicht integriert.", "watches.subStrava": "Aktivitäts-Portal", "watches.st.avail": "Verfügbar", "watches.st.planned": "wartet auf Freigabe", "watches.st.import": "Polar API", "watches.st.no": "Nicht möglich", "watches.st.nope": "nope", "account.recordModeMoved": "Die Aufzeichnungsrate stellst du jetzt pro Uhr bei deinen verbundenen Uhren ein."]
        mdeAT.merge(bdeAT4) { a, _ in a }
        r["de-AT"] = mdeAT
