        men.merge(ben0) { a, _ in a }
        let ben1: [String: String] = ["brett.erkl.titel": "What is board attitude?", "brett.erkl.was": "If your phone is fixed to the board during the session, its gyroscope measures how the board pitches and rolls – right at the source instead of at your wrist.", "brett.erkl.wie": "How it works: put your phone in a waterproof case, fix it flat on the deck and start recording in the Pumpfoil app on the phone. Your watch can record at the same time. The analysis usually notices by itself that the phone was on the board.", "brett.erkl.bringt": "What you get out of it: you see how steady your board is while pumping, how much it pitches and rolls per pump, and whether that differs between foils, turns and straights. Every such recording also helps improve pump detection for the watch.", "brett.erkl.daten": "The data you get: pitch and roll per pump, lean, cadence, turns versus straights and the heave (the up-and-down movement, once the pump rhythm is detected reliably) – per run, and here as an overview of all runs and per foil.", "brett.erkl.mehr": "Learn more", "region.earth": "Earth", "region.eu": "Europe", "region.af": "Africa", "region.as": "Asia", "region.na": "North America", "region.sa": "South America", "region.oc": "Oceania", "profile.landNone": "Not specified", "share.errImage": "Could not create image", "spot.windTitle": "Wind window", "spot.windText": "{n} wind sessions, mostly at {a}–{b} km/h", "spot.windNote": "Where the wind came from during wing, kite and parawing sessions at this spot (model wind).", "tab.noData": "No data here yet.", "fontscale.label": "Font size", "fontscale.hint": "Make everything larger for better readability.", "sd.avgHrTotal": "Ø heart rate overall", "sd.whoLiked": "Who?", "sd.likes": "Likes", "comments.title": "Comments", "comments.empty": "No comments yet. Write the first one!", "comments.placeholder": "Write a comment …", "comments.offOwner": "Comments are switched off for your sessions.", "comments.offLink": "Switch them on in your profile", "comments.settingHint": "Others can comment on your sessions. You can delete other people's comments on your sessions. When switched off, comments are hidden for everyone, including those already written.", "comments.settingSwitch": "Allow comments on my sessions", "act.title": "New comments & likes", "act.comment": "commented", "act.like": "likes your session", "act.likeMany": "and {n} more like your session", "act.session": "Session from {d}", "profile.land": "Nationality", "profile.landHint": "Optional. If you set it, your flag appears in the leaderboards, their share images and on your profile page.", "tab.events": "Events", "tab.logbook": "Logbook", "tab.rules": "Rules", "team.einladungUngueltig": "This invite link is no longer valid. Ask the team lead for a new one.", "team.feed30": "Sessions of team members from the last 30 days.", "team.alleMeine": "All my teams", "sessions.uploadReplaceAsk": "This ride is already here (session #{id}), but the file is a different one. Delete the old session and replace it with this file?\n\nTo just trim it, you don't need a new file: use “{trim}” in the session."]
