        let bit3: [String: String] = ["guide.a.s2b": ".", "guide.a.s3Title": "3. Campi dati:", "guide.a.s3": "pagine scorrevoli direttamente sull'orologio (configurabili nella scheda « Campi dati »). Pulsante Stop all'inizio e alla fine delle pagine.", "guide.a.s4Title": "4. Registra:", "guide.a.s4": "apri l'app → Avvia → foila → Stop. La registrazione funziona anche offline; la sincronizzazione avviene automaticamente una volta online.", "guide.wearSub": "Samsung Galaxy Watch, Google Pixel Watch …", "guide.w.s1Title": "1. Installa l'app sull'orologio:", "guide.w.s1": "apri il Play Store sull'orologio e cerca «Pumpfoil».", "guide.w.s1Note": "Il Play Store sul telefono installa l'app per telefono — l'app per orologio è un'installazione separata, sull'orologio stesso.", "guide.w.s2Title": "2. Connetti — facoltativo:", "guide.w.s2a": "come Apple Watch — registrazione senza account possibile, connetti più tardi; oppure nell'app dell'orologio « Connetti » → « Genera codice » e inserisci il codice qui nella scheda", "guide.w.s2b": ".", "guide.w.s3Title": "3. Campi dati:", "guide.w.s3": "pagine scorrevoli, configurabili nella scheda « Campi dati ».", "guide.w.s4Title": "4. Registra:", "guide.w.s4": "apri l'app → Avvia → foila → Stop. Registrazione offline + sincronizzazione automatica.", "guide.amazfitSub": "Il nostro registratore funziona su orologi Amazfit con Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 e altri).", "guide.z.store": "Installa l’app Zepp, poi trova Pumpfoil nel suo App Store integrato:", "guide.z.s1": "Installa l’app Zepp (sopra) e associa il tuo Amazfit come al solito.", "guide.z.s2": "Nell’app Zepp: Profilo → il tuo Amazfit → App Store → cerca «Pumpfoil» → Installa.", "guide.z.s3": "Apri Pumpfoil sull’orologio, scorri fino a ›Connetti‹ per un codice, poi inseriscilo in ", "guide.z.s4": "Premi START per registrare. GPS e battito vengono caricati automaticamente via Wi-Fi/telefono.", "guide.huaweiSub": "Il nostro registratore funziona su HUAWEI WATCH 5 (HarmonyOS 5/6). Una volta collegato, l’orologio carica da solo – senza app sul telefono.", "guide.h.s1": "Sull’orologio apri AppGallery, cerca “Pumpfoil” e installa l’app. Consenti posizione e sensori corporei.", "guide.h.s2": "Apri Pumpfoil, scorri in alto fino alle impostazioni e tocca ›pumpfoil.org‹ – l’orologio mostra un codice. Inseriscilo in ", "guide.h.s3": "Tocca START. Tieni premuti STOP e Pausa per 2 secondi, tocca Scarta due volte.", "guide.h.s4": "Dopo lo stop l’orologio carica da solo appena ha Internet (Wi-Fi o tramite il telefono collegato). Sulla schermata iniziale compare “All sent”.", "guide.preview": "Anteprima sull'orologio:", "guide.previewVer": "Anteprima sull'orologio (v1.0.24):", "guide.cap.gStart": "Avvio: GPS pronto → START", "guide.cap.gSettings": "Tieni premuto MENU → Impostazioni", "guide.cap.gPairCode": "Connetti — codice sull'orologio", "guide.cap.gPairOk": "Connesso", "guide.cap.gAlarm1": "Scegli l'allarme", "guide.cap.gAlarm2": "Allarme — foil / valori fissi", "guide.cap.gAlarm3": "Allarme — attivazione", "guide.cap.onFoil": "Durante la sessione", "guide.cap.wConnect": "Collega — codice sull’orologio", "guide.cap.wStart": "Avvio", "guide.cap.wAlarm": "Scegli allarme / foil", "guide.cap.wStats": "Riepilogo: tempo / distanza / FC", "guide.cap.wRun": "Run attuale", "guide.cap.wStop": "Tieni premuto → stop", "guide.cap.aConnect": "Connetti — genera codice", "guide.cap.aCode": "Codice → su pumpfoil.org"]
