        let bfi1: [String: String] = ["brett.erkl.titel": "Mikä on laudan asento?", "brett.erkl.was": "Kun puhelin on kiinnitetty lautaan session ajaksi, sen gyroskooppi mittaa, miten lauta nyökkää ja kallistuu – suoraan lähteellä eikä ranteessa.", "brett.erkl.wie": "Näin se toimii: laita puhelin vesitiiviiseen koteloon, kiinnitä se tasaisesti kanteen ja aloita tallennus puhelimen Pumpfoil-sovelluksessa. Kello voi tallentaa samaan aikaan. Analyysi huomaa yleensä itse, että puhelin oli laudalla.", "brett.erkl.bringt": "Mitä siitä saat: näet, kuinka vakaasti lauta kulkee pumpatessa, kuinka paljon se nyökkää ja kallistuu jokaisella pumpulla ja eroaako se foilien, kaarteiden ja suorien välillä. Jokainen tällainen tallennus auttaa myös parantamaan kellon pumppujen tunnistusta.", "brett.erkl.daten": "Saamasi tiedot: nyökkäys ja kallistus pumppua kohden, kallistuma, tahti, kaarteet vastaan suorat ja pystyliike (kun pumpputahti tunnistetaan varmasti) – lenkeittäin ja tässä yhteenvetona kaikista lenkeistä ja foileittain.", "brett.erkl.mehr": "Lue lisää", "region.earth": "Maa", "region.eu": "Eurooppa", "region.af": "Afrikka", "region.as": "Aasia", "region.na": "Pohjois-Amerikka", "region.sa": "Etelä-Amerikka", "region.oc": "Oseania", "profile.landNone": "Ei ilmoitettu", "share.errImage": "Kuvaa ei voitu luoda", "spot.windTitle": "Tuuli-ikkuna", "spot.windText": "{n} tuulisessiota, yleensä {a}–{b} km/h", "spot.windNote": "Mistä tuuli tuli wing-, kite- ja parawing-sessioissa tällä spotilla (mallituuli).", "tab.noData": "Täällä ei ole vielä tietoja.", "fontscale.label": "Tekstin koko", "fontscale.hint": "Suurenna kaikki paremman luettavuuden vuoksi.", "sd.avgHrTotal": "Ø syke yhteensä", "sd.whoLiked": "Kuka?", "sd.likes": "Tykkäykset", "comments.title": "Kommentit", "comments.empty": "Ei vielä kommentteja. Kirjoita ensimmäinen!", "comments.placeholder": "Kirjoita kommentti …", "comments.offOwner": "Kommentit on poistettu käytöstä sessioillasi.", "comments.offLink": "Ota käyttöön