        let bnl4: [String: String] = ["guide.cap.aStart": "Start", "guide.cap.aAlarm": "Alarm kiezen + activeren", "guide.cap.aStop": "Stop", "guide.cap.aUpload": "Upload na het stoppen", "guide.settings.title": "Instellingen voor je horloge", "guide.settings.intro": "Zodra het horloge gekoppeld is, vind je voor elk twee instellingen onder ", "guide.settings.intro2": ". Ze werken op het horloge zelf — het pikt ze op zodra je de app daar de volgende keer opent, geen update nodig. Als batterijduur voor jou telt, zijn dit de knoppen.", "guide.settings.recordTitle": "Opnamemodus (alle horloges):", "guide.settings.record": "25 Hz, 10 Hz of alleen gps. 10 Hz bespaart batterij en kost bijna niets — we hebben beide frequenties over dezelfde sessies laten lopen: je pomptelling blijft binnen een half procent, en welke delen als foilen tellen is voor 99,9 % identiek.", "guide.settings.gnssTitle": "Satellietsystemen (alleen Garmin):", "guide.settings.gnss": "Standaard is het beste wat je horloge kan — alle systemen over twee frequentiebanden. Dat vindt je positie het snelst en houdt hem het best vast, maar het kost echt batterij. «Zonder tweede frequentieband» houdt alle systemen en laat alleen de dure extra band vallen: het meest bespaard voor het minst verloren.", "guide.settings.gpsWarn": "Alleen gps bespaart het meest, maar gooit pomptelling, cadans en glijfases helemaal weg — precies de getallen waarvoor deze app bestaat. Kies dat alleen als je horloge de sessie anders niet volhoudt.", "guide.settings.zepp": "Op Amazfit heeft de opnamemodus nog geen effect — het horloge neemt op met zijn eigen frequentie. Taal, pauzeweergave en eigen lay-outs haalt het wel hiervandaan.", "watches.title": "Ondersteunde horloges", "watches.intro": "Welk horloge levert welke gegevens — jij beslist. We willen op termijn alle gangbare sporthorloges aansluiten.", "watches.colDevice": "Horloge", "watches.colGps": "GPS · afstand · snelheid", "watches.colHr": "Hartslag", "watches.colPump": "Pumps & glijfases", "watches.colStatus": "Status", "watches.foot": "Pumps & glijfases hebben ruwe versnelling (≥25 Hz) direct van het horloge nodig. GPS-stats zijn bij veel merken ook via FIT-/data-import te analyseren.", "watches.legYes": "volledig ondersteund", "watches.legPartial": "beperkt", "watches.legNo": "niet beschikbaar", "watches.linkAccount": "Accountkoppeling beschikbaar", "watches.linkViaSuunto": "via Mi Fitness → Suunto", "watches.nGarmin": "Oudere modellen zonder ruwe accel: GPS-stats worden toch geanalyseerd.", "watches.nApple": "Ruwe versnelling via Core Motion.", "watches.nWear": "Draait op elk Wear OS 3+-horloge — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "Sensortoegang afhankelijk van het model.", "watches.nHuaweiW5": "Uploadt zelf na koppelen met een code, zonder telefoon-app. Nieuw in AppGallery.", "watches.nHuawei": "In ontwikkeling: opnemen op het horloge, overdracht via de Pumpfoil-app op een Android-telefoon. Welke gegevens de horloges leveren, moet nog getest worden.", "watches.nPolar": "Account koppelen → trainingen importeren (GPS + HR). De hoogfrequente accel-stream voor de pompdetectie levert de API-export niet (alleen via een aparte BLE-sensor).", "watches.nSuunto": "Account koppelen → trainingen importeren (GPS + HR). De hoogfrequente accel-stream voor de pompdetectie levert de FIT-export (nog) niet.", "watches.nXiaomi": "Geen app op het horloge (Xiaomi laat geen apps van derden toe). Maar Mi Fitness stuurt je trainingen officieel naar de Suunto-app — koppel Suunto en ze komen hier binnen. Uitleg bij ‘Gekoppelde accounts’.", "watches.nFitbit": "Apps van derden zijn stopgezet.", "watches.nStrava": "Import zou technisch kunnen, maar levert via de API geen hoogfrequente ruwe accel (dus geen pompdetectie) en zit achter een paywall + API-voorwaarden die niet bij het open project passen — daarom bewust niet geïntegreerd.", "watches.subStrava": "activiteitenportaal", "watches.st.avail": "Bes