        let bcs1: [String: String] = ["brett.erkl.titel": "Co je poloha prkna?", "brett.erkl.was": "Když máš telefon během vyjížďky pevně na prkně, jeho gyroskop měří, jak prkno kývá a naklání se – přímo u zdroje, ne na zápěstí.", "brett.erkl.wie": "Jak na to: dej telefon do vodotěsného obalu, připevni ho naplocho na palubu a spusť záznam v aplikaci Pumpfoil v telefonu. Hodinky můžou nahrávat současně. Že byl telefon na prkně, pozná vyhodnocení většinou samo.", "brett.erkl.bringt": "Co ti to dá: uvidíš, jak klidně prkno při pumpování leží, jak moc při každém pumpu kývá a naklání se a jestli se to liší mezi foily, zatáčkami a rovinkami. Každý takový záznam navíc pomáhá zlepšit rozpoznávání pumpů pro hodinky.", "brett.erkl.daten": "Jaká data dostaneš: kývání a náklon na pump, náklon, kadenci, zatáčky proti rovinkám a vertikální pohyb (jakmile je rytmus pumpování spolehlivě rozpoznán) – pro každou jízdu a tady jako přehled všech jízd a podle foilu.", "brett.erkl.mehr": "Více informací", "region.earth": "Země", "region.eu": "Evropa", "region.af": "Afrika", "region.as": "Asie", "region.na": "Severní Amerika", "region.sa": "Jižní Amerika", "region.oc": "Oceánie", "profile.landNone": "Neuvedeno", "share.errImage": "Obrázek se nepodařilo vytvořit", "spot.windTitle": "Větrné okno", "spot.windText": "{n} větrných session, většinou při {a}–{b} km/h", "spot.windNote": "Odkud foukal vítr při wing, kite a parawing session na tomto spotu (modelový vítr).", "tab.noData": "Zatím tu nejsou žádná data.", "fontscale.label": "Velikost písma", "fontscale.hint": "Pro lepší čitelnost zvětšit vše.", "sd.avgHrTotal": "Ø tep celkem", "sd.whoLiked": "Kdo?", "sd.likes": "Líbí se", "comments.title": "Komentáře", "comments.empty": "Zatím žádné komentáře. Napiš první!", "comments.placeholder": "Napsat komentář …", "comments.offOwner": "Komentáře jsou u tvých sessions vypnuté.", "comments.offLink": "Zapnout v profilu", "comments.settingHint": "Ostatní mohou komentovat tvé sessions. Cizí komentáře pod svými sessions můžeš smazat. Když je vypneš, komentáře jsou skryté pro všechny, i ty už napsané.", "comments.settingSwitch": "Povolit komentáře pod mými sessions", "act.title": "Nové komentáře & lajky", "act.comment": "okomentoval(a)", "act.like": "se líbí tvoje session", "act.likeMany": "a {n} další lajkují tvoji session", "act.session": "Session z {d}", "profile.land": "Národnost", "profile.landHint": "Nepovinné. Když ji vyplníš, tvoje vlajka se zobrazí v žebříčcích, jejich obrázcích ke sdílení a na tvé profilové stránce.", "tab.events": "Akce", "tab.logbook": "Deník", "tab.rules": "Pravidla", "team.einladungUngueltig": "Tento odkaz s pozvánkou už neplatí. Požádej vedení týmu o nový.", "team.feed30": "Vyjížďky členů týmu za posledních 30 dní.", "team.alleMeine": "Všechny moje týmy", "sessions.uploadReplaceAsk": "Tahle jízda už tu je (session #{id}), ale soubor je jiný. Smazat starou session a nahradit ji tímto souborem?\n\nJen zkrátit jde i bez nového souboru: v session přes „{trim}“."]
        mcs.merge(bcs1) { a, _ in a }
        let bcs2: [String: String] = ["team.regeln.intro": "Jak fungují týmy na pumpfoil.org: kdo co vidí, jak se hodnotí a co se stane při smazání.", "team.regeln.was.titel": "Co je tým?", "team.regeln.was.text": "Pevná skupina s vlastními žebříčky, akcemi a týmovým chatem.\nKaždý může zakládat týmy, i víc najednou, a být ve více týmech.\nNový tým funguje hned, přes odkazy s pozvánkou.", "team.regeln.rollen.titel": "Role", "team.regeln.rollen.text": "Vedoucí smí všechno: nastavení, žebříčky, akce, jmenování moderátorů, předání vedení a smazání týmu.\nModerátoři přijímají nebo odmítají žádosti, odebírají členy a zakládají akce. Nic jiného nemění.\nČlenové vidí v týmu všechno a můžou kdykoli odejít.\nVedoucí může odejít, až když předá vedení.", "team.regeln.beitreten.titel": "Přidání do týmu", "team.regeln.beitreten.text": "Pokud tým přijímá přihlášky, je na jeho stránce tlačítko „Přidat se“. Podle nastavení jsi hned členem, nebo rozhodne vedoucí či moderátor.\nJsou dva odkazy s pozvánkou: jeden, se kterým jsi hned členem, a druhý, kterým pošleš žádost. Oba jsou i jako QR kód.\nKdo ještě nemá účet, založí si ho a pak je rovnou v týmu, případně má žádost odeslanou.\nNově vytvořený odkaz nahradí starý, který pak přestane platit.\nKaždým vstupem souhlasíš s tím, že žebříčky týmu můžou být veřejné, i když zrovna nejsou.\nU žádosti vidí vedoucí a moderátoři, na kterých spotech a v jakých sportech jsi dosud jezdil (jen počet sessions).", "team.regeln.oeffentlich.titel": "Co je veřejné", "team.regeln.oeffentlich.text": "Uvnitř smí tým všechno. Navenek se objeví, až když jsme si jednou prohlédli a schválili jeho název, adresu, popis, znak a barvu.\nBanner týmu prochází stejným schválením jako znak. Kterou část je vidět, volí vedoucí bez nového schválení; když banner odebere, zmizí hned i z veřejné stránky.\nKdyž schválený tým změní svůj vzhled, v týmu to platí hned, navenek až po novém schválení.\nSchválené týmy jsou na stránce „Všechny týmy“, jejich probíhající a nadcházející akce v komunitě.\nKdyž vedoucí zveřejní žebříčky, vidí je každý, i bez přihlášení, ale jen pořadí, zobrazované jméno, iniciály a hodnotu. Vyjížďky, spoty, data a profilové fotky vidí jen přihlášení uživatelé.\nVyhledávače stránky týmů neindexují.\nKdo vidí seznam členů, určuje vedoucí: jen členové, nebo všichni přihlášení.", "team.regeln.bestenlisten.titel": "Žebříčky", "team.regeln.bestenlisten.text": "Za každého se počítá jen jeden záznam: nejlepší hodnota z jedné vyjížďky, nebo u součtů všechno ve zvoleném období dohromady.\nPočítají se všechny vyjížďky členů, i ty z doby před vstupem. Kdo odejde, hned ze žebříčků zmizí.\nU akcí to platí jen do konce, viz „Akce“.\nPlatí stejné filtry jako u komunitních rekordů: smazané, nahlášené, nezařazené a probíhající nahrávky se nepočítají.\nKaždý žebříček lze omezit na jeden sport, jeden rozsah foilů, nahrávky s pohybovými daty, telefon na desce nebo týmové spoty.\nKdyž je zapnuté „Skrýt místo“, vyjížďka se nikdy nezapočítá pro konkrétní spot.\nPři shodě je výš ten, kdo hodnotu zajel dřív.", "team.regeln.statistik.titel": "Týmové součty", "team.regeln.statistik.text": "Nad žebříčky jsou součty všech členů ve zvoleném období: pumpnutí, vzdálenost a čas na foilu, vyjížďky, jízdy a kolik členů bylo aktivních.\nŽebříček tým proti týmu záměrně není.", "team.regeln.logbuch.titel": "Deník", "team.regeln.logbuch.text": "Deník zaznamenává, kdo kdy překonal který týmový rekord. Aktualizuje se každou noc.\nPrvní záznam žebříčku je stav v první noci po jeho založení.\nU nejlepších hodnot se počítá každé zlepšení, i vlastní. U součtů se počítá jen to, když se někdo dostane do čela.\nKdyž rekord klesne, protože byla smazána vyjížďka nebo někdo odešel, upraví se to potichu, bez záznamu.", "team.regeln.chat.titel": "Týmový chat", "team.regeln.chat.text": "Týmový chat čtou a píšou do něj jen aktivní členové. Kdo jen poslal žádost, nevidí ho.\nPro ostatní se nikde neobjeví, ani mezi aktivními chaty.\nKdo odejde nebo je odebrán, hned ztratí přístup a nedostává už žádná upozornění.", "team.regeln.loeschen.titel": "Smazání týmu", "team.regeln.loeschen.text": "Smazat tým může jen vedoucí, a jen když pro potvrzení napíše název týmu.\nTým pak zmizí pro všechny: členství, žebříčky, deník, akce i týmový chat. Data zatím uchováváme, aby šel omylem smazaný tým obnovit.\nAdresa týmu zůstane zablokovaná a nikdy se nepřidělí jinému týmu.", "team.regeln.konto.titel": "Když se smaže účet", "team.regeln.konto.text": "Člověk zmizí ze všech týmů a žebříčků a také ze zmrazených výsledků akcí. Ti pod ním se posunou nahoru.\nPokud vedl tým, převezme ho nejdéle sloužící moderátor, jinak nejdéle sloužící člen. Pokud už nikdo nezbyl, tým se smaže.", "team.regeln.haftung.titel": "Odpovědnost", "team.regeln.haftung.text": "Akce pořádají samy týmy. pumpfoil.org nemá žádný vliv na akce ani na sliby v nich dané, finanční či jiné, a nepřebírá za ně žádnou odpovědnost. Právní cesta je vyloučena. Platby a všechny další dohody si pořadatelé a účastníci řeší sami, nezávisle na pumpfoil.org.\nStejně tak pumpfoil.org nepřebírá žádnou odpovědnost za to, zda jsou naměřené hodnoty a data správné nebo zda nebyly zmanipulovány. Zobrazuje se to, co z nahraných dat spočítá veřejný zdrojový kód na GitHubu; žádné další záruky neexistují.", "team.regeln.events.titel": "Akce", "notif.typeComment": "Komentáře k mým sessions", "home.topCommented": "Nejvíce komentované", "theme.dark": "Tmavý", "theme.light": "Světlý", "tech.hLong": "Jízdy od 20 s – klidná střední část", "tech.hShort": "Jízdy pod 20 s – celá jízda", "tech.lShort": "Jízdy mezi 5 a 20 s, vždy včetně startu a konce.", "tech.allRuns": "Všechny jízdy", "account.tabGuide": "Návod", "tab.watchSettings": "Nastavení", "account.tabConnect": "Připojit", "account.tabFaces": "Ciferníky / Datová pole", "account.tabAlarm": "On-foil alarm", "account.tabCompat": "Kompatibilita", "account.toLayouts": "Vlastní rozvržení", "tab.watchSettingsUhr": "Nastavení hodinek", "guide.appleSub": "watchOS 9+", "guide.a.s1Title": "1. Nainstalovat aplikaci:", "guide.a.s1": "z App Store.", "guide.a.s2Title": "2. Propojit — volitelné:", "guide.a.s2a": "Můžeš nahrávat hned bez účtu („Propojit později“) a vyjížďku nahrát později. K přiřazení: v aplikaci na hodinkách „Propojit“ → „Vygenerovat párovací kód“ — zobrazený kód zadej zde v záložce"]
        mcs.merge(bcs2) { a, _ in a }
        let bcs3: [String: String] = ["guide.a.s2b": "zadat.", "guide.a.s3Title": "3. Datová pole:", "guide.a.s3": "přímo na hodinkách listovatelné stránky (konfigurovatelné v záložce „Datová pole“). Tlačítko Stop na začátku a na konci stránek.", "guide.a.s4Title": "4. Nahrávání:", "guide.a.s4": "Otevři aplikaci → Start → foil → Stop. Nahrávání běží i offline; sync proběhne automaticky, jakmile jsi online.", "guide.wearSub": "Samsung Galaxy Watch, Google Pixel Watch …", "guide.w.s1Title": "1. Nainstalovat aplikaci v hodinkách:", "guide.w.s1": "otevři Play Store v hodinkách a najdi „Pumpfoil“.", "guide.w.s1Note": "Play Store v telefonu nainstaluje aplikaci pro telefon — aplikace pro hodinky se instaluje zvlášť, přímo v hodinkách.", "guide.w.s2Title": "2. Propojit — volitelné:", "guide.w.s2a": "jako u Apple Watch — nahrávat bez účtu je možné, propojit později; nebo v aplikaci na hodinkách „Propojit“ → „Vygenerovat párovací kód“ a kód zadej zde v záložce", "guide.w.s2b": "zadat.", "guide.w.s3Title": "3. Datová pole:", "guide.w.s3": "listovatelné stránky, konfigurovatelné v záložce „Datová pole“.", "guide.w.s4Title": "4. Nahrávání:", "guide.w.s4": "Otevři aplikaci → Start → foil → Stop. Offline nahrávání + automatický sync.", "guide.amazfitSub": "Náš rekordér běží na hodinkách Amazfit se Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 a další).", "guide.z.store": "Nainstaluj aplikaci Zepp a najdi Pumpfoil v jejím App Store:", "guide.z.s1": "Nainstaluj aplikaci Zepp (výše) a spáruj své Amazfit jako obvykle.", "guide.z.s2": "V aplikaci Zepp: Profil → tvé Amazfit → App Store → vyhledej „Pumpfoil“ → Instalovat.", "guide.z.s3": "Otevři Pumpfoil na hodinkách, přejeď na ›Připojit‹ pro kód a zadej jej v ", "guide.z.s4": "Stiskni START pro záznam. GPS a tep se nahrají automaticky přes Wi-Fi/telefon.", "guide.huaweiSub": "Náš záznamník běží na HUAWEI WATCH 5 (HarmonyOS 5/6). Po propojení hodinky nahrávají samy – bez aplikace v telefonu.", "guide.h.s1": "Na hodinkách otevři AppGallery, vyhledej „Pumpfoil“ a nainstaluj aplikaci. Povol polohu a tělesné senzory.", "guide.h.s2": "Otevři Pumpfoil, přejeď nahoru do nastavení a klepni na ›pumpfoil.org‹ – hodinky ukážou kód. Zadej ho v ", "guide.h.s3": "Klepni na START. STOP a Pauzu drž 2 sekundy, Zahodit klepni dvakrát.", "guide.h.s4": "Po zastavení hodinky nahrají samy, jakmile mají internet (Wi-Fi nebo přes spárovaný telefon). Na úvodní obrazovce se pak ukáže „All sent“.", "guide.preview": "Takhle to vypadá na hodinkách:", "guide.previewVer": "Takhle to vypadá na hodinkách (v1.0.24):", "guide.cap.gStart": "Start: GPS připraveno → START", "guide.cap.gSettings": "Podrž MENU → Nastavení", "guide.cap.gPairCode": "Propojit — kód na hodinkách", "guide.cap.gPairOk": "Propojeno", "guide.cap.gAlarm1": "Vybrat alarm", "guide.cap.gAlarm2": "Alarm — foil / pevné hodnoty", "guide.cap.gAlarm3": "Alarm — spouštění", "guide.cap.onFoil": "Během jízdy", "guide.cap.wConnect": "Propojit — kód na hodinkách", "guide.cap.wStart": "Start", "guide.cap.wAlarm": "Vybrat alarm / foil", "guide.cap.wStats": "Přehled: čas / vzdálenost / tep", "guide.cap.wRun": "Aktuální jízda", "guide.cap.wStop": "Podrž → Stop", "guide.cap.aConnect": "Propojit — vygenerovat kód", "guide.cap.aCode": "Kód → na pumpfoil.org"]
        mcs.merge(bcs3) { a, _ in a }
        let bcs4: [String: String] = ["guide.cap.aStart": "Start", "guide.cap.aAlarm": "Vybrat alarm + spouštění", "guide.cap.aStop": "Stop", "guide.cap.aUpload": "Upload po zastavení", "guide.settings.title": "Nastavení pro tvoje hodinky", "guide.settings.intro": "Jakmile jsou hodinky připojené, najdeš pro každé dvě nastavení pod ", "guide.settings.intro2": ". Působí přímo na hodinky — převezmou je, až tam příště otevřeš aplikaci, aktualizace není potřeba. Pokud ti jde o výdrž, tohle jsou ty páky.", "guide.settings.recordTitle": "Režim nahrávání (všechny hodinky):", "guide.settings.record": "25 Hz, 10 Hz nebo jen GPS. 10 Hz šetří baterii a nestojí skoro nic — obě frekvence jsme prohnali stejnými vyjížďkami: počet pumpnutí sedí do půl procenta a to, které části se počítají jako foiling, je z 99,9 % totožné.", "guide.settings.gnssTitle": "Satelitní systémy (jen Garmin):", "guide.settings.gnss": "Ve výchozím stavu je to to nejlepší, co tvoje hodinky umí — všechny systémy přes dvě frekvenční pásma. To najde pozici nejrychleji a nejlépe ji drží, ale stojí to opravdu baterii. „Bez druhého frekvenčního pásma“ ponechá všechny systémy a vypustí jen to drahé pásmo navíc: nejvíc ušetřeno za nejmíň ztraceno.", "guide.settings.gpsWarn": "Jen GPS ušetří nejvíc, ale úplně zahodí počet pumpnutí, kadenci i fáze klouzání — přesně ta čísla, kvůli kterým tahle aplikace existuje. Vol to jen tehdy, když hodinky jinak vyjížďku nevydrží.", "guide.settings.zepp": "Na Amazfitu režim nahrávání zatím nemá vliv — hodinky nahrávají vlastní frekvencí. Jazyk, zobrazení pauzy a vlastní rozvržení si odsud ale berou.", "watches.title": "Podporované hodinky", "watches.intro": "Které hodinky poskytují která data — rozhoduješ ty. Dlouhodobě chceme napojit všechny běžné sportovní hodinky.", "watches.colDevice": "Hodinky", "watches.colGps": "GPS · vzdálenost · rychlost", "watches.colHr": "Tep", "watches.colPump": "Pumpnutí a fáze klouzání", "watches.colStatus": "Stav", "watches.foot": "Pumpnutí a fáze klouzání potřebují surové zrychlení (≥25 Hz) přímo z hodinek. GPS statistiky lze u mnoha značek vyhodnotit i přes FIT/import dat.", "watches.legYes": "plně podporováno", "watches.legPartial": "omezeně", "watches.legNo": "není dostupné", "watches.linkAccount": "Propojení účtu dostupné", "watches.linkViaSuunto": "přes Mi Fitness → Suunto", "watches.nGarmin": "Starší modely bez surového accelu: GPS statistiky se přesto vyhodnotí.", "watches.nApple": "Surové zrychlení přes Core Motion.", "watches.nWear": "Běží na jakýchkoli hodinkách Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "Přístup k senzorům podle modelu.", "watches.nHuaweiW5": "Po propojení kódem nahrává sama, bez aplikace v telefonu. Nově v AppGallery.", "watches.nHuawei": "V přípravě: záznam na hodinkách, přenos přes aplikaci Pumpfoil v telefonu s Androidem. Jaká data hodinky dodají, je ještě potřeba otestovat.", "watches.nPolar": "Propoj účet → importuj tréninky (GPS + tep). Vysokofrekvenční accel stream pro rozpoznání pumpnutí API export neposkytuje (jen přes samostatný BLE senzor).", "watches.nSuunto": "Propoj účet → importuj tréninky (GPS + tep). Vysokofrekvenční accel stream pro rozpoznání pumpnutí FIT export (zatím) neposkytuje.", "watches.nXiaomi": "Žádná aplikace v hodinkách (Xiaomi cizí aplikace nepovoluje). Mi Fitness ale oficiálně posílá tvoje tréninky do aplikace Suunto — propoj Suunto a dorazí k nám. Návod v „Propojené účty“.", "watches.nFitbit": "Aplikace třetích stran byly ukončeny.", "watches.nStrava": "Import by byl technicky proveditelný, ale přes API neposkytuje vysokofrekvenční surový accel (tedy žádné rozpoznání pumpnutí) a je za paywallem + API podmínkami, které se k otevřenému projektu nehodí — proto záměrně neintegrováno.", "watches.subStrava": "portál aktivit", "watches.st.avail": "Dostupné", "watches.st.planned": "čeká na schválení", "watches.st.import": "Polar API", "watches.st.no": "Není možné", "watches.st.nope": "ne", "account.recordModeMoved": "Frekvenci nahrávání teď nastavuješ pro každé hodinky zvlášť u svých připojených hodinek."]
        mcs.merge(bcs4) { a, _ in a }
        r["cs"] = mcs
        var mpl: [String: String] = [:]
        let bpl0: [String: String] = ["tab.overview": "Przegląd", "tab.team": "Drużyna", "tab.stats": "Statystyki", "tab.insights": "Wskaźniki", "nav.settings": "Ustawienia", "mySpots.title": "Moje spoty", "mySpots.empty": "Brak jeszcze sesji na żadnym spocie.", "mySpots.last": "ostatnio {d}", "mySpots.since": "od {d}", "mySpots.sports": "Dyscypliny", "mySpots.all": "Wszystkie ({n})", "sessions.title": "Sesje", "tab.weather": "Pogoda", "tab.descriptions": "Opisy", "tab.spotPage": "Strona spotu", "phome.profileHint": "Twoja strona profilu, tak jak mogą ją zobaczyć inni.", "phome.asFriends": "Znajomi", "phome.asAll": "Wszyscy", "phome.previewHidden": "Twoja strona profilu jest ukryta dla innych; widzą ją tylko znajomi.", "ptab.privacy": "Prywatność", "ptab.watches": "Zegarki", "ptab.me": "Ja", "ptab.riding": "Pływanie", "ptab.display": "Wygląd", "ptab.account": "Konto", "gear.title": "Sprzęt", "gear.mastShim": "Maszt i shim", "gear.searchHint": "Szukaj po marce lub modelu, aby coś dodać.", "gear.noHits": "Brak wyników.", "tab.rankings": "Rekordy i ranking", "tab.media": "Media", "land.teamsTitle": "Drużyny i wydarzenia", "home.leaderboards": "Rankingi", "watchStats.sectionFoiling": "Foiling wg zegarka", "tab.map": "Mapa", "tab.list": "Lista", "tab.routes": "Trasy", "tab.watchAccounts": "Zegarek i konta", "period.yesterday": "Wczoraj", "tab.noRecords": "Nie ma tu jeszcze rekordów.", "setup.stabSearch": "Szukaj stabilizatora…", "foils.hint": "Zaznacz swoje foile i wybierz jeden jako domyślny (★). Domyślny można nadpisać w każdej sesji.", "profile.avatar": "Zdjęcie profilowe", "profile.dataTitle": "Dane i konto", "profile.calculator": "Kalkulator foili"]
