        let bpl4: [String: String] = ["guide.cap.aStart": "Start", "guide.cap.aAlarm": "Wybierz alarm + wyzwalanie", "guide.cap.aStop": "Stop", "guide.cap.aUpload": "Wysyłka po zatrzymaniu", "guide.settings.title": "Ustawienia dla Twojego zegarka", "guide.settings.intro": "Gdy zegarek jest już połączony, dla każdego z nich znajdziesz dwie regulacje w ", "guide.settings.intro2": ". Działają na sam zegarek — przejmie je przy następnym otwarciu aplikacji, bez aktualizacji. Jeśli zależy Ci na czasie pracy baterii, to są właśnie te dźwignie.", "guide.settings.recordTitle": "Tryb nagrywania (wszystkie zegarki):", "guide.settings.record": "25 Hz, 10 Hz albo tylko GPS. 10 Hz oszczędza baterię i prawie nic nie kosztuje — puściliśmy obie częstotliwości na tych samych sesjach: Twoja liczba pomp mieści się w pół procenta, a to, które fragmenty liczą się jako foiling, jest identyczne w 99,9%.", "guide.settings.gnssTitle": "Systemy satelitarne (tylko Garmin):", "guide.settings.gnss": "Domyślnie jest to najlepsze, co potrafi Twój zegarek — każdy system na dwóch pasmach częstotliwości. To najszybciej znajduje pozycję i najlepiej ją trzyma, ale kosztuje sporo baterii. „Bez drugiego pasma częstotliwości” zachowuje wszystkie systemy i rezygnuje tylko z kosztownego dodatkowego pasma: najwięcej oszczędności przy najmniejszej stracie.", "guide.settings.gpsWarn": "Tylko GPS oszczędza najwięcej, ale całkowicie wyrzuca liczbę pomp, kadencję i fazy szybowania — dokładnie te liczby, dla których ta aplikacja istnieje. Wybierz to tylko wtedy, gdy zegarek inaczej nie wytrzyma całej sesji.", "guide.settings.zepp": "Na Amazficie tryb nagrywania nie działa jeszcze — zegarek nagrywa ze swoją własną częstotliwością. Język, widok pauzy i własne układy przejmuje jednak stąd.", "watches.title": "Wspierane zegarki", "watches.intro": "Który zegarek daje jakie dane — decydujesz Ty. Docelowo chcemy wspierać wszystkie popularne zegarki sportowe.", "watches.colDevice": "Zegarek", "watches.colGps": "GPS · dystans · prędkość", "watches.colHr": "Tętno", "watches.colPump": "Pompy i fazy szybowania", "watches.colStatus": "Status", "watches.foot": "Pompy i fazy szybowania wymagają surowego przyspieszenia (≥25 Hz) wprost z zegarka. Statystyki GPS można analizować przez import FIT/danych dla wielu marek.", "watches.legYes": "w pełni wspierane", "watches.legPartial": "ograniczone", "watches.legNo": "niedostępne", "watches.linkAccount": "Można połączyć konto", "watches.linkViaSuunto": "przez Mi Fitness → Suunto", "watches.nGarmin": "Starsze modele bez surowego akcelerometru: statystyki GPS i tak są analizowane.", "watches.nApple": "Surowe przyspieszenie przez Core Motion.", "watches.nWear": "Działa na każdym zegarku z Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "Dostęp do czujników zależy od modelu.", "watches.nHuaweiW5": "Po połączeniu kodem sam wysyła dane, bez aplikacji w telefonie. Nowość w AppGallery.", "watches.nHuawei": "W przygotowaniu: nagrywanie na zegarku, przesyłanie przez aplikację Pumpfoil na telefonie z Androidem. Jakie dane dostarczają zegarki, trzeba jeszcze przetestować.", "watches.nPolar": "Połącz konto → importuj treningi (GPS + tętno). Eksport z API nie zawiera strumienia surowego przyspieszenia o wysokiej częstotliwości, potrzebnego do wykrywania pomp (tylko przez osobny czujnik BLE).", "watches.nSuunto": "Połącz konto → importuj treningi (GPS + tętno). Eksport FIT (jeszcze) nie zawiera strumienia surowego przyspieszenia o wysokiej częstotliwości, potrzebnego do wykrywania pomp.", "watches.nXiaomi": "Brak aplikacji na zegarku (Xiaomi nie dopuszcza aplikacji innych firm). Ale Mi Fitness oficjalnie wysyła treningi do aplikacji Suunto — połącz Suunto, a trafią do nas. Instrukcja w „Połączone konta”.", "watches.nFitbit": "Aplikacje firm trzecich zostały wycofane.", "watches.nStrava": "Import byłby technicznie możliwy, ale API nie udostępnia surowych danych akcelerometru o wysokiej częstotliwości (czyli brak wykrywania pompowań), a do tego jest za paywallem i ma warunki API, które nie pasują do otwartego projektu — świadomie niezintegrowane.", "watches.subStrava": "portal aktywności", "watches.st.avail": "Dostępne", "watches.st.planned": "czeka na zatwierdzenie", "watches.st.import": "API Polar", "watches.st.no": "Niemożliwe", "watches.st.nope": "nie", "account.recordModeMoved": "Częstotliwość nagrywania ustawia się teraz osobno dla każdego zegarka, przy Twoich połączonych zegarkach."]
        mpl.merge(bpl4) { a, _ in a }
