        let bpt4: [String: String] = ["guide.cap.aStart": "Iniciar", "guide.cap.aAlarm": "Escolher alarme + disparo", "guide.cap.aStop": "Parar", "guide.cap.aUpload": "Enviar após parar", "guide.settings.title": "Ajustes para o seu relógio", "guide.settings.intro": "Assim que o relógio estiver conectado, você encontra dois controles para cada um em ", "guide.settings.intro2": ". Eles agem no próprio relógio — ele os pega da próxima vez que você abrir o app lá, sem precisar atualizar. Se a autonomia importa para você, são estas as alavancas.", "guide.settings.recordTitle": "Modo de gravação (todos os relógios):", "guide.settings.record": "25 Hz, 10 Hz ou só GPS. 10 Hz economiza bateria e quase não custa nada — rodamos as duas frequências nas mesmas sessões: sua contagem de bombeios fica dentro de meio por cento, e quais trechos contam como foiling é 99,9 % idêntico.", "guide.settings.gnssTitle": "Sistemas de satélites (só Garmin):", "guide.settings.gnss": "Por padrão é o melhor que seu relógio consegue — todos os sistemas em duas bandas de frequência. Isso encontra sua posição mais rápido e a segura melhor, mas custa bateria de verdade. «Sem segunda banda de frequência» mantém todos os sistemas e abre mão só da banda extra cara: o máximo de economia com a menor perda.", "guide.settings.gpsWarn": "Só GPS é o que mais economiza, mas joga fora por completo a contagem de bombeios, a cadência e as fases de planeio — justamente os números pelos quais este app existe. Escolha isso só se o relógio não aguentar a sessão de outro jeito.", "guide.settings.zepp": "No Amazfit o modo de gravação ainda não tem efeito — o relógio grava na frequência dele mesmo. O idioma, a visualização de pausa e os layouts próprios ele pega daqui.", "watches.title": "Relógios suportados", "watches.intro": "Qual relógio dá quais dados — você decide. No longo prazo queremos dar suporte a todos os relógios esportivos comuns.", "watches.colDevice": "Relógio", "watches.colGps": "GPS · distância · velocidade", "watches.colHr": "Frequência cardíaca", "watches.colPump": "Pumps e fases de planeio", "watches.colStatus": "Status", "watches.foot": "Pumps e fases de planeio precisam de aceleração bruta (≥25 Hz) direto do relógio. As estatísticas de GPS podem ser analisadas via importação FIT/dados para muitas marcas.", "watches.legYes": "totalmente suportado", "watches.legPartial": "limitado", "watches.legNo": "não disponível", "watches.linkAccount": "Vínculo de conta disponível", "watches.linkViaSuunto": "via Mi Fitness → Suunto", "watches.nGarmin": "Modelos mais antigos sem accel bruta: as estatísticas de GPS ainda são analisadas.", "watches.nApple": "Aceleração bruta via Core Motion.", "watches.nWear": "Roda em qualquer relógio Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "O acesso ao sensor depende do modelo.", "watches.nHuaweiW5": "Envia sozinho depois de vinculado com um código, sem app no celular. Novo na AppGallery.", "watches.nHuawei": "Em desenvolvimento: gravação no relógio, transferência pelo app Pumpfoil num celular Android. Ainda falta testar quais dados cada relógio fornece.", "watches.nPolar": "Vincule sua conta → importe treinos (GPS + FC). A exportação da API não inclui o fluxo de accel bruta em alta taxa necessário para detectar pump (só via um sensor BLE separado).", "watches.nSuunto": "Vincule sua conta → importe treinos (GPS + FC). A exportação FIT (ainda) não inclui o fluxo de accel bruta em alta taxa necessário para detectar pump.", "watches.nXiaomi": "Sem app no relógio (a Xiaomi não permite apps de terceiros). Mas o Mi Fitness envia oficialmente os seus treinos para o app Suunto — conecte o Suunto e eles chegam aqui. Instruções em «Contas vinculadas».", "watches.nFitbit": "Os apps de terceiros foram descontinuados.", "watches.nStrava": "Uma importação seria tecnicamente possível, mas a API não fornece dados brutos do acelerômetro em alta frequência (ou seja, sem detecção de bombeios), e fica atrás de um paywall com termos de API que não combinam com um projeto aberto — deliberadamente não integrado.", "watches.subStrava": "portal de atividades", "watches.st.avail": "Disponível", "watches.st.planned": "aguardando aprovação", "watches.st.import": "API Polar", "watches.st.no": "Não é possível", "watches.st.nope": "não", "account.recordModeMoved": "A taxa de gravação agora é definida por relógio, junto com seus relógios vinculados."]
