        let bru4: [String: String] = ["guide.cap.aStart": "Старт", "guide.cap.aAlarm": "Выберите сигнал + срабатывание", "guide.cap.aStop": "Стоп", "guide.cap.aUpload": "Загрузка после остановки", "guide.settings.title": "Настройки для твоих часов", "guide.settings.intro": "Как только часы подключены, для каждых из них ты найдёшь две настройки в разделе ", "guide.settings.intro2": ". Они действуют на сами часы — те подхватят их при следующем открытии приложения, обновление не нужно. Если для тебя важно время работы, это те самые рычаги.", "guide.settings.recordTitle": "Режим записи (все часы):", "guide.settings.record": "25 Гц, 10 Гц или только GPS. 10 Гц экономит батарею и почти ничего не стоит — мы прогнали обе частоты по одним и тем же сессиям: счётчик помпинга укладывается в полпроцента, а какие участки считаются катанием, совпадает на 99,9 %.", "guide.settings.gnssTitle": "Спутниковые системы (только Garmin):", "guide.settings.gnss": "По умолчанию — лучшее, на что способны твои часы: все системы в двух частотных диапазонах. Так позиция находится быстрее всего и держится лучше всего, но это по-настоящему стоит батареи. «Без второго частотного диапазона» сохраняет все системы и отказывается только от дорогого дополнительного диапазона: максимум экономии при минимуме потерь.", "guide.settings.gpsWarn": "Только GPS экономит больше всего, но полностью выбрасывает счётчик помпинга, каденс и фазы глиссирования — как раз те числа, ради которых существует это приложение. Выбирай это, только если иначе часам не хватит на всю сессию.", "guide.settings.zepp": "На Amazfit режим записи пока не действует — часы записывают со своей частотой. Язык, вид паузы и собственные раскладки они при этом берут отсюда.", "watches.title": "Поддерживаемые часы", "watches.intro": "Какие часы дают какие данные — решаете вы. В долгосрочной перспективе мы хотим поддержать все распространённые спортивные часы.", "watches.colDevice": "Часы", "watches.colGps": "GPS · дистанция · скорость", "watches.colHr": "Пульс", "watches.colPump": "Помпинг и фазы скольжения", "watches.colStatus": "Статус", "watches.foot": "Помпингу и фазам скольжения нужно сырое ускорение (≥25 Hz) прямо с часов. GPS-статистику можно проанализировать через импорт FIT/данных для многих брендов.", "watches.legYes": "полностью поддерживается", "watches.legPartial": "ограниченно", "watches.legNo": "недоступно", "watches.linkAccount": "Доступна привязка аккаунта", "watches.linkViaSuunto": "через Mi Fitness → Suunto", "watches.nGarmin": "Старые модели без сырого акселерометра: GPS-статистика всё равно анализируется.", "watches.nApple": "Сырое ускорение через Core Motion.", "watches.nWear": "Работает на любых часах с Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "Доступ к датчикам зависит от модели.", "watches.nHuaweiW5": "После привязки по коду загружает данные сама, без приложения на телефоне. Новинка в AppGallery.", "watches.nHuawei": "В работе: запись на часах, передача через приложение Pumpfoil на телефоне с Android. Какие данные дают часы, ещё нужно проверить.", "watches.nPolar": "Привяжите аккаунт → импорт тренировок (GPS + пульс). Экспорт через API не включает высокочастотный поток сырого ускорения, нужный для распознавания помпинга (только через отдельный BLE-датчик).", "watches.nSuunto": "Привяжите аккаунт → импорт тренировок (GPS + пульс). Экспорт FIT (пока) не включает высокочастотный поток сырого ускорения, нужный для распознавания помпинга.", "watches.nXiaomi": "Приложения на часах нет (Xiaomi не допускает сторонние). Зато Mi Fitness официально отправляет тренировки в приложение Suunto — подключи Suunto, и они придут к нам. Инструкция в «Связанные аккаунты».", "watches.nFitbit": "Сторонние приложения прекращены.", "watches.nStrava": "Импорт технически был бы возможен, но API не отдаёт сырые данные акселерометра с высокой частотой (значит, никакого распознавания помпинга), к тому же он за платной стеной с условиями API, которые не подходят открытому проекту — намеренно не интегрировано.", "watches.subStrava": "портал активностей", "watches.st.avail": "Доступно", "watches.st.planned": "ожидает одобрения", "watches.st.import": "Polar API", "watches.st.no": "Невозможно", "watches.st.nope": "нет", "account.recordModeMoved": "Частота записи теперь задаётся для каждых часов, в разделе связанных часов."]
