        let bnb1: [String: String] = ["brett.erkl.titel": "Hva er brettets stilling?", "brett.erkl.was": "Hvis telefonen er festet til brettet under økten, måler gyroskopet hvordan brettet nikker og ruller – rett ved kilden i stedet for på håndleddet.", "brett.erkl.wie": "Slik gjør du det: legg telefonen i et vanntett etui, fest den flatt på dekket og start opptaket i Pumpfoil-appen på telefonen. Klokka kan ta opp samtidig. At telefonen lå på brettet, oppdager analysen som regel selv.", "brett.erkl.bringt": "Hva du får ut av det: du ser hvor stødig brettet ligger når du pumper, hvor mye det nikker og ruller per pump, og om det er forskjell mellom foiler, svinger og rettstrekninger. Hvert slikt opptak hjelper også med å forbedre pumpgjenkjenningen for klokka.", "brett.erkl.daten": "Dataene du får: nikk og rull per pump, krengning, takt, svinger mot rettstrekninger og opp-og-ned-bevegelsen (når pumperytmen er sikkert gjenkjent) – per runde, og her som oversikt over alle runder og per foil.", "brett.erkl.mehr": "Les mer", "region.earth": "Jorden", "region.eu": "Europa", "region.af": "Afrika", "region.as": "Asia", "region.na": "Nord-Amerika", "region.sa": "Sør-Amerika", "region.oc": "Oseania", "profile.landNone": "Ikke oppgitt", "share.errImage": "Kunne ikke lage bilde", "spot.windTitle": "Vindvindu", "spot.windText": "{n} vindøkter, oftest ved {a}–{b} km/t", "spot.windNote": "Hvor vinden kom fra under wing-, kite- og parawing-økter på denne spoten (modellvind).", "tab.noData": "Ingen data her ennå.", "fontscale.label": "Skriftstørrelse", "fontscale.hint": "Gjør alt større så det blir lettere å lese.", "sd.avgHrTotal": "Ø puls totalt", "sd.whoLiked": "Hvem?", "sd.likes": "Likes", "comments.title": "Kommentarer", "comments.empty": "Ingen kommentarer ennå. Skriv den første!", "comments.placeholder": "Skriv en kommentar …", "comments.offOwner": "Kommentarer er slått av for øktene dine.", "comments.offLink": "Slå dem på i profilen", "comments.settingHint": "Andre kan kommentere øktene dine. Du kan slette andres kommentarer under øktene dine. Når de er slått av, er kommentarer skjult for alle, også de som allerede er skrevet.", "comments.settingSwitch": "Tillat kommentarer på øktene mine", "act.title": "Nye kommentarer og likes", "act.comment": "kommenterte", "act.like": "liker økten din", "act.likeMany": "og {n} til liker økten din", "act.session": "Økt fra {d}", "profile.land": "Nasjonalitet", "profile.landHint": "Valgfritt. Hvis du fyller det inn, vises flagget ditt i topplistene, bildene som kan deles og på profilsiden din.", "tab.events": "Arrangementer", "tab.logbook": "Loggbok", "tab.rules": "Regler", "team.einladungUngueltig": "Denne invitasjonslenken gjelder ikke lenger. Be lagets leder om en ny.", "team.feed30": "Økter fra lagmedlemmer de siste 30 dagene.", "team.alleMeine": "Alle lagene mine", "sessions.uploadReplaceAsk": "Denne turen finnes allerede (økt #{id}), men filen er en annen. Slette den gamle økten og erstatte den med denne filen?\n\nVil du bare kutte den, trenger du ingen ny fil: bruk «{trim}» i økten."]
        mnb.merge(bnb1) { a, _ in a }
        let bnb2: [String: String] = ["team.regeln.intro": "Slik fungerer lag på pumpfoil.org: hvem som ser hva, hvordan det telles, og hva som skjer ved sletting.", "team.regeln.was.titel": "Hva er et lag?", "team.regeln.was.text": "En fast gruppe med egne topplister, arrangementer og lagchat.\nAlle kan starte lag, også flere, og være med i flere lag.\nEt nytt lag fungerer med en gang, via invitasjonslenker.", "team.regeln.rollen.titel": "Roller", "team.regeln.rollen.text": "Lederen kan gjøre alt: innstillinger, topplister, arrangementer, utnevne moderatorer, overlate lederrollen og slette laget.\nModeratorer godtar eller avslår forespørsler, fjerner medlemmer og oppretter arrangementer. Ellers endrer de ingenting.\nMedlemmer ser alt i laget og kan melde seg ut når som helst.\nLederen kan først melde seg ut etter å ha overlatt lederrollen.", "team.regeln.beitreten.titel": "Bli med", "team.regeln.beitreten.text": "Tar et lag imot påmeldinger, finnes det en «Bli med»-knapp på siden. Avhengig av innstillingen er du medlem med en gang, eller lederen eller en moderator bestemmer.\nDet finnes to invitasjonslenker: én som gjør deg til medlem med en gang, og én som sender en forespørsel. Begge finnes også som QR-kode.\nDen som ikke har konto, oppretter en og er deretter rett i laget, eller har sendt forespørselen.\nEn nylaget lenke erstatter den gamle, som da slutter å virke.\nHver gang du blir med, godtar du at lagets topplister kan være offentlige, også om de ikke er det akkurat nå.\nVed en forespørsel ser lederen og moderatorene hvilke spotter og idretter du har vært ute på så langt (bare antall økter).", "team.regeln.oeffentlich.titel": "Hva som er offentlig", "team.regeln.oeffentlich.text": "Internt kan et lag gjøre alt. Utad vises det først når vi har sett på og godkjent navn, adresse, beskrivelse, våpenskjold og farge.\nLagbanneret går gjennom samme godkjenning som våpenskjoldet. Hvilken del som vises, velger lederen uten ny godkjenning; fjerner lederen banneret, forsvinner det straks også fra den offentlige siden.\nEndrer et godkjent lag utseendet sitt, gjelder det i laget med en gang, utad først etter ny godkjenning.\nGodkjente lag står på siden «Alle lag», og deres pågående og kommende arrangementer i fellesskapet.\nGjør lederen topplistene offentlige, ser alle dem, også uten innlogging, men bare plass, visningsnavn, initialer og verdi. Økter, spots, datoer og profilbilder ser bare innloggede brukere.\nSøkemotorer indekserer ikke lagsider.\nLederen bestemmer hvem som ser medlemslisten: bare medlemmer eller alle innloggede.", "team.regeln.bestenlisten.titel": "Topplister", "team.regeln.bestenlisten.text": "Hver person teller bare én gang: sin beste verdi fra én økt, eller ved summer alt i valgt periode lagt sammen.\nAlle øktene til medlemmene teller, også de fra før innmeldingen. Den som melder seg ut, forsvinner fra listene med en gang.\nFor arrangementer gjelder det bare til slutten, se «Arrangementer».\nDe samme filtrene gjelder som for fellesskapsrekordene: slettede, rapporterte, ikke tilordnede og pågående opptak teller ikke.\nHver toppliste kan begrenses til én sport, ett foilområde, opptak med bevegelsesdata, telefon på brettet eller lagspotsene.\nEr «Skjul stedet» slått på, teller økten aldri for en bestemt spot.\nVed likt resultat ligger den foran som kjørte verdien først.", "team.regeln.statistik.titel": "Lagsummer", "team.regeln.statistik.text": "Over topplistene står summene for alle medlemmer i valgt periode: pumper, distanse og tid på foil, økter, runs og hvor mange medlemmer som var aktive.\nEn rangering lag mot lag finnes bevisst ikke.", "team.regeln.logbuch.titel": "Loggbok", "team.regeln.logbuch.text": "Loggboken holder rede på hvem som slo hvilken lagrekord, og når. Den oppdateres hver natt.\nDen første oppføringen i en toppliste er stillingen den første natten etter at den ble opprettet.\nFor beste verdier teller hver forbedring, også din egen. For summer teller det bare når noen tar ledelsen.\nSynker en rekord fordi en økt ble slettet eller noen meldte seg ut, rettes det stille, uten oppføring.", "team.regeln.chat.titel": "Lagchat", "team.regeln.chat.text": "Bare aktive medlemmer kan lese og skrive i lagchatten. Den som bare har sendt en forespørsel, ser den ikke.\nDen dukker ikke opp noe sted for andre, heller ikke blant de aktive chattene.\nDen som melder seg ut eller blir fjernet, mister tilgangen med en gang og får ingen flere varsler.", "team.regeln.loeschen.titel": "Slette laget", "team.regeln.loeschen.text": "Bare lederen kan slette laget, og bare ved å skrive inn lagnavnet som bekreftelse.\nDa er laget borte for alle: medlemskap, lister, loggbok, arrangementer og lagchatten. Vi tar vare på dataene inntil videre, så et lag som er slettet ved en feil kan gjenopprettes.\nAdressen til laget forblir sperret og gis aldri til et annet lag.", "team.regeln.konto.titel": "Når en konto slettes", "team.regeln.konto.text": "Personen forsvinner fra alle lag og topplister, også fra frosne arrangementsresultater. De nedenfor rykker opp.\nLedet personen et lag, tar moderatoren med lengst fartstid over, ellers medlemmet med lengst fartstid. Er det ingen igjen, slettes laget.", "team.regeln.haftung.titel": "Ansvar", "team.regeln.haftung.text": "Arrangementene drives av lagene selv. pumpfoil.org har ingen innflytelse på arrangementer eller på løfter som gis i dem, økonomiske eller andre, og tar intet ansvar for dem. Rettslig prøving er utelukket. Betalinger og alle andre avtaler ordner arrangører og deltakere seg imellom, uavhengig av pumpfoil.org.\nLikeledes tar pumpfoil.org intet ansvar for om målte verdier og data er riktige eller har blitt manipulert. Det som vises, er det den offentlige kildekoden på GitHub beregner ut fra de opplastede dataene; det gis ingen andre løfter.", "team.regeln.events.titel": "Arrangementer", "notif.typeComment": "Kommentarer på øktene mine", "home.topCommented": "Mest kommentert", "theme.dark": "Mørkt", "theme.light": "Lyst", "tech.hLong": "Runs fra 20 s – rolig midtdel", "tech.hShort": "Runs under 20 s – hele runen", "tech.lShort": "Runder mellom 5 og 20 s, inkludert start og slutt.", "tech.allRuns": "Alle runs", "account.tabGuide": "Veiledning", "tab.watchSettings": "Innstillinger", "account.tabConnect": "Klokkene mine", "account.tabFaces": "Urskiver / Datafelt", "account.tabAlarm": "På-foil-alarm", "account.tabCompat": "Kompatibilitet", "account.toLayouts": "Egne oppsett", "tab.watchSettingsUhr": "Klokkeinnstillinger", "guide.appleSub": "watchOS 9+", "guide.a.s1Title": "1. Installer appen:", "guide.a.s1": "fra App Store.", "guide.a.s2Title": "2. Koble til — valgfritt:", "guide.a.s2a": "Du kan ta opp med en gang uten konto (“Koble til senere”) og laste opp økta etterpå. For å knytte den til: i klokke-appen “Koble til” → “Lag koblingskode” — skriv inn koden som vises, her i fanen"]
        mnb.merge(bnb2) { a, _ in a }
        let bnb3: [String: String] = ["guide.a.s2b": ".", "guide.a.s3Title": "3. Datafelt:", "guide.a.s3": "sider du sveiper mellom rett på klokka (settes opp i fanen “Datafelt”). Stopp-knapp først og sist i sidene.", "guide.a.s4Title": "4. Ta opp:", "guide.a.s4": "åpne appen → Start → foil → Stopp. Opptak fungerer også offline; synk skjer automatisk når du er på nett.", "guide.wearSub": "Samsung Galaxy Watch, Google Pixel Watch …", "guide.w.s1Title": "1. Installer appen på klokka:", "guide.w.s1": "åpne Play Store på klokka og søk etter “Pumpfoil”.", "guide.w.s1Note": "Play Store på telefonen installerer telefonappen — klokke-appen installeres separat, på klokka selv.", "guide.w.s2Title": "2. Koble til — valgfritt:", "guide.w.s2a": "som Apple Watch — opptak uten konto går fint, koble til senere; eller i klokke-appen “Koble til” → “Lag koblingskode” og skriv inn koden her i fanen", "guide.w.s2b": ".", "guide.w.s3Title": "3. Datafelt:", "guide.w.s3": "sider du sveiper mellom, settes opp i fanen “Datafelt”.", "guide.w.s4Title": "4. Ta opp:", "guide.w.s4": "åpne appen → Start → foil → Stopp. Opptak offline + automatisk synk.", "guide.amazfitSub": "Opptakeren vår kjører på Amazfit-klokker med Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 med flere).", "guide.z.store": "Hent Zepp-appen, og finn Pumpfoil i dens innebygde App Store:", "guide.z.s1": "Installer Zepp-appen (over) og par Amazfit-klokka i den som vanlig.", "guide.z.s2": "I Zepp-appen: Profil → din Amazfit → App Store → søk “Pumpfoil” → Installer.", "guide.z.s3": "Åpne Pumpfoil på klokka, sveip til ›Koble til‹ for en kode, og skriv den inn under ", "guide.z.s4": "Trykk START for å ta opp. GPS og puls lastes opp automatisk over Wi-Fi eller telefonen.", "guide.huaweiSub": "Opptakeren vår kjører på HUAWEI WATCH 5 (HarmonyOS 5/6). Når den er koblet til, laster klokken opp selv – uten telefonapp.", "guide.h.s1": "Åpne AppGallery på klokken, søk etter «Pumpfoil» og installer appen. Tillat posisjon og kroppssensorer.", "guide.h.s2": "Åpne Pumpfoil, sveip opp til innstillingene og trykk på ›pumpfoil.org‹ – klokken viser en kode. Skriv den inn under ", "guide.h.s3": "Trykk START. Hold STOP og Pause i 2 sekunder, trykk Forkast to ganger.", "guide.h.s4": "Etter stopp laster klokken opp selv så snart den har internett (Wi-Fi eller via den sammenkoblede telefonen). Startskjermen viser da «All sent».", "guide.preview": "Slik ser det ut på klokka:", "guide.previewVer": "Slik ser det ut på klokka (v1.0.24):", "guide.cap.gStart": "Start: GPS klar → START", "guide.cap.gSettings": "Hold MENU → Innstillinger", "guide.cap.gPairCode": "Koble til — kode på klokka", "guide.cap.gPairOk": "Tilkoblet", "guide.cap.gAlarm1": "Velg alarm", "guide.cap.gAlarm2": "Alarm — foil / faste verdier", "guide.cap.gAlarm3": "Alarm — utløser", "guide.cap.onFoil": "Mens du kjører", "guide.cap.wConnect": "Koble til — kode på klokka", "guide.cap.wStart": "Start", "guide.cap.wAlarm": "Velg alarm / foil", "guide.cap.wStats": "Oversikt: tid / distanse / puls", "guide.cap.wRun": "Nåværende run", "guide.cap.wStop": "Hold → stopp", "guide.cap.aConnect": "Koble til — lag kode", "guide.cap.aCode": "Kode → på pumpfoil.org"]
        mnb.merge(bnb3) { a, _ in a }
        let bnb4: [String: String] = ["guide.cap.aStart": "Start", "guide.cap.aAlarm": "Velg alarm + utløser", "guide.cap.aStop": "Stopp", "guide.cap.aUpload": "Opplasting etter stopp", "guide.settings.title": "Innstillinger for klokka di", "guide.settings.intro": "Når klokka er tilkoblet, finner du to innstillinger for hver av dem under ", "guide.settings.intro2": ". De virker på selve klokka — den henter dem neste gang du åpner appen der, ingen oppdatering nødvendig. Er batteritid viktig for deg, er det disse som gjelder.", "guide.settings.recordTitle": "Opptaksmodus (alle klokker):", "guide.settings.record": "25 Hz, 10 Hz eller kun GPS. 10 Hz sparer batteri og koster nesten ingenting — vi kjørte begge ratene over de samme øktene: pumpetellingen din havner innenfor en halv prosent, og hvilke deler som teller som foiling er 99,9 % identisk.", "guide.settings.gnssTitle": "Satellittsystemer (kun Garmin):", "guide.settings.gnss": "Standard er det beste klokka di får til — alle systemer over to frekvensbånd. Det finner posisjonen din raskest og holder best på den, men det koster virkelig batteri. «Uten andre frekvensbånd» beholder alle systemene og dropper bare det dyre ekstrabåndet: mest spart for minst tapt.", "guide.settings.gpsWarn": "Kun GPS sparer mest, men kaster bort pumpetelling, kadens og glidefaser fullstendig — nettopp tallene denne appen finnes for. Velg det bare hvis klokka di ellers ikke holder gjennom økta.", "guide.settings.zepp": "På Amazfit har opptaksmodus ingen effekt ennå — klokka tar opp med sin egen rate. Språk, pausevisning og egne oppsett henter den derimot herfra.", "watches.title": "Støttede klokker", "watches.intro": "Hvilken klokke gir hvilke data — du bestemmer. På sikt vil vi støtte alle vanlige sportsklokker.", "watches.colDevice": "Klokke", "watches.colGps": "GPS · distanse · fart", "watches.colHr": "Puls", "watches.colPump": "Pump og glidefaser", "watches.colStatus": "Status", "watches.foot": "Pump og glidefaser krever rå akselerasjon (≥25 Hz) direkte fra klokka. GPS-statistikk kan analyseres via FIT-/dataimport for mange merker.", "watches.legYes": "full støtte", "watches.legPartial": "begrenset", "watches.legNo": "ikke tilgjengelig", "watches.linkAccount": "Kontokobling tilgjengelig", "watches.linkViaSuunto": "via Mi Fitness → Suunto", "watches.nGarmin": "Eldre modeller uten rå akselerasjon: GPS-statistikk analyseres likevel.", "watches.nApple": "Rå akselerasjon via Core Motion.", "watches.nWear": "Kjører på alle klokker med Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.", "watches.nAmazfit": "Sensortilgang avhenger av modellen.", "watches.nHuaweiW5": "Laster opp selv etter tilkobling med kode, uten telefonapp. Ny i AppGallery.", "watches.nHuawei": "Under arbeid: opptak på klokken, overføring via Pumpfoil-appen på en Android-telefon. Hvilke data klokkene leverer, må fortsatt testes.", "watches.nPolar": "Koble til kontoen din → importer treningsøkter (GPS + puls). API-eksporten inneholder ikke den høyfrekvente strømmen av rå akselerasjon som trengs for pumpegjenkjenning (bare via en egen BLE-sensor).", "watches.nSuunto": "Koble til kontoen din → importer treningsøkter (GPS + puls). FIT-eksporten inneholder (ennå) ikke den høyfrekvente strømmen av rå akselerasjon som trengs for pumpegjenkjenning.", "watches.nXiaomi": "Ingen app på klokka (Xiaomi tillater ikke tredjepartsapper). Men Mi Fitness sender treningene dine offisielt til Suunto-appen — koble til Suunto, så kommer de hit. Veiledning under «Tilkoblede kontoer».", "watches.nFitbit": "Apper fra tredjeparter ble avviklet.", "watches.nStrava": "Import ville vært teknisk mulig, men API-et gir ikke rå akselerometerdata med høy rate (altså ingen pumpegjenkjenning), og det ligger bak en betalingsmur med API-vilkår som ikke passer et åpent prosjekt — bevisst ikke integrert.", "watches.subStrava": "aktivitetsportal", "watches.st.avail": "Tilgjengelig", "watches.st.planned": "venter på godkjenning", "watches.st.import": "Polar API", "watches.st.no": "Ikke mulig", "watches.st.nope": "nei", "account.recordModeMoved": "Opptaksraten settes nå per klokke, sammen med klokkene du har koblet til."]
